<script setup lang="ts">
import type { CommonArea, Reservation } from '~/domain/reservation'
import { useReservations } from '~/composables/use-reservations'

const props = defineProps<{ areas: CommonArea[]; reservations: Reservation[]; residentId?: string; canManage?: boolean }>()
const emit = defineEmits<{ reservationCreated: []; reservationCancelled: []; openDetails: [id: string] }>()
const { createReservation, cancelReservation } = useReservations()

type ReservationView = 'mine' | 'new'
type ReservationFilter = 'all' | 'pending' | 'approved' | 'cancelled' | 'finished'
const view = ref<ReservationView>('mine')
const filter = ref<ReservationFilter>('all')
const selectedAreaId = ref(props.areas[0]?.id ?? '')
const visibleMonth = ref(new Date(2026, 8, 1))
const selectedDate = ref('2026-09-24')
const selectedSlots = ref<string[]>([])
const showTimeSelection = ref(false)
const bookingMode = ref<'time' | 'day'>('time')
const draggingSlots = ref(false)
const dragAnchor = ref<string | null>(null)
const didDragSlots = ref(false)
const submitting = ref(false)
const cancellingId = ref<string | null>(null)
const feedback = ref('')
const todayKey = '2026-09-15'
const selectedArea = computed(() => props.areas.find(area => area.id === selectedAreaId.value) ?? props.areas[0])
const monthLabel = computed(() => new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(visibleMonth.value).replace(/^./, value => value.toUpperCase()))
const weekdays = ['Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom']
const dateKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const formatDate = (date: string) => new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(`${date}T12:00:00`))
const selectedDateObject = computed(() => new Date(`${selectedDate.value}T12:00:00`))
const fullDateLabel = computed(() => new Intl.DateTimeFormat('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' }).format(selectedDateObject.value).replace(/^./, value => value.toUpperCase()))

const myReservations = computed(() => [...props.reservations].filter(item => !props.residentId || item.residentId === props.residentId).sort((a, b) => `${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`)))
const isFinished = (reservation: Reservation) => reservation.date < todayKey || (reservation.date === todayKey && (reservation.endTime ?? '23:59') <= '00:00')
const reservationState = (reservation: Reservation): ReservationFilter => ['cancelled', 'rejected'].includes(reservation.status) ? 'cancelled' : isFinished(reservation) ? 'finished' : reservation.status as 'pending' | 'approved'
const filteredReservations = computed(() => myReservations.value.filter(item => filter.value === 'all' || reservationState(item) === filter.value).sort((a, b) => Number(isFinished(a)) - Number(isFinished(b))))
const filterItems: Array<{ key: ReservationFilter; label: string }> = [{ key: 'all', label: 'Todas' }, { key: 'pending', label: 'Pendentes' }, { key: 'approved', label: 'Confirmadas' }, { key: 'cancelled', label: 'Canceladas' }, { key: 'finished', label: 'Finalizadas' }]
const areaById = computed(() => new Map(props.areas.map(area => [area.id, area])))
const areaName = (id: string) => areaById.value.get(id)?.name ?? 'Área comum'
const statusLabel = (state: ReservationFilter) => ({ approved: 'Confirmada', pending: 'Pendente', cancelled: 'Cancelada', finished: 'Finalizada', all: 'Todas' } as Record<ReservationFilter, string>)[state]
const statusIcon = (state: ReservationFilter) => ({ approved: '✓', pending: '◷', cancelled: '×', finished: '✓', all: '•' }[state] ?? '•')
const canCancel = (reservation: Reservation) => ['pending', 'approved'].includes(reservation.status) && !isFinished(reservation)
function resetTimeSelection() { selectedSlots.value = []; bookingMode.value = 'time'; showTimeSelection.value = false; feedback.value = '' }
function openTimeSelection() { showTimeSelection.value = true }
function setBookingMode(mode: 'time' | 'day') { bookingMode.value = mode; if (mode === 'day') selectedSlots.value = [] }
function openNewReservation() { view.value = 'new'; resetTimeSelection() }
function openReservationDetails(reservation: Reservation) { selectedAreaId.value = reservation.areaId; selectedDate.value = reservation.date; visibleMonth.value = new Date(`${reservation.date}T12:00:00`); view.value = 'new'; resetTimeSelection() }
function viewReservationDetails(reservation: Reservation) { if (props.canManage) emit('openDetails', reservation.id); else openReservationDetails(reservation) }
async function cancel(reservation: Reservation) { cancellingId.value = reservation.id; try { await cancelReservation(reservation.id); emit('reservationCancelled') } finally { cancellingId.value = null } }

const parseMinutes = (value: string) => { const [hour = 0, minute = 0] = value.split(':').map(Number); return hour * 60 + minute }
const slots = computed(() => { const area = selectedArea.value; if (!area?.openingTime || !area.closingTime) return []; const result: string[] = []; for (let start = parseMinutes(area.openingTime); start < parseMinutes(area.closingTime); start += 30) { const end = Math.min(start + 30, parseMinutes(area.closingTime)); result.push(`${String(Math.floor(start / 60)).padStart(2, '0')}:${String(start % 60).padStart(2, '0')} – ${String(Math.floor(end / 60)).padStart(2, '0')}:${String(end % 60).padStart(2, '0')}`) } return result })
const reservationForDate = (date: string) => props.reservations.filter(item => item.areaId === selectedArea.value?.id && item.date === date && ['pending', 'approved'].includes(item.status))
const isSlotOccupied = (slot: string, date = selectedDate.value) => { const [fromText = '00:00', toText = '00:00'] = slot.split(' – '); const from = parseMinutes(fromText); const to = parseMinutes(toText); return reservationForDate(date).some(item => parseMinutes(item.startTime ?? '00:00') < to && parseMinutes(item.endTime ?? '23:59') > from) }
const dateStatus = (date: string) => { if (!selectedArea.value || selectedArea.value.status === 'unavailable' || !slots.value.length) return 'unavailable'; const occupied = slots.value.filter(slot => isSlotOccupied(slot, date)).length; return occupied === 0 ? 'available' : occupied >= slots.value.length ? 'occupied' : 'partial' }
const calendarDays = computed(() => { const year = visibleMonth.value.getFullYear(); const month = visibleMonth.value.getMonth(); const offset = (new Date(year, month, 1).getDay() + 6) % 7; return Array.from({ length: 42 }, (_, index) => { const date = new Date(year, month, 1 - offset + index); return { date, key: dateKey(date), current: date.getMonth() === month } }) })
const selectedStatus = computed(() => dateStatus(selectedDate.value))
const occupiedSlots = computed(() => slots.value.filter(slot => isSlotOccupied(slot)))
const availableSlots = computed(() => slots.value.filter(slot => !isSlotOccupied(slot)))
const occupiedPeriods = computed(() => reservationForDate(selectedDate.value).map(item => item.startTime && item.endTime ? `${item.startTime} – ${item.endTime}` : 'Dia inteiro'))
const selectedInterval = computed(() => { if (!selectedSlots.value.length) return ''; const ordered = [...selectedSlots.value].sort((a, b) => parseMinutes(a) - parseMinutes(b)); return `${ordered[0]?.split(' – ')[0]} – ${ordered.at(-1)?.split(' – ')[1]}` })
const availabilityLabel = (status: string) => ({ available: 'Disponível', partial: 'Parcialmente ocupado', occupied: 'Ocupado', unavailable: 'Indisponível' }[status] ?? status)
function changeMonth(amount: number) { visibleMonth.value = new Date(visibleMonth.value.getFullYear(), visibleMonth.value.getMonth() + amount, 1) }
function selectDate(date: string) { selectedDate.value = date; resetTimeSelection() }
function toggleSlot(slot: string) {
  const current = [...selectedSlots.value].sort((a, b) => parseMinutes(a) - parseMinutes(b))
  if (current.includes(slot)) { selectedSlots.value = []; return }
  if (!current.length) { selectedSlots.value = [slot]; return }
  const firstStart = parseMinutes(current[0] ?? '00:00')
  const lastEnd = parseMinutes((current.at(-1) ?? '00:00 – 00:00').split(' – ')[1] ?? '00:00')
  const [slotStart = '00:00', slotEnd = '00:00'] = slot.split(' – ')
  const extendsAfter = parseMinutes(slotStart) === lastEnd
  const extendsBefore = parseMinutes(slotEnd) === firstStart
  selectedSlots.value = (current.length < 4 && (extendsAfter || extendsBefore)) ? [...current, slot] : [slot]
}
function startSlotDrag(slot: string) { draggingSlots.value = true; dragAnchor.value = slot; didDragSlots.value = false }
function extendSlotDrag(slot: string) {
  if (!draggingSlots.value || !dragAnchor.value || isSlotOccupied(slot)) return
  didDragSlots.value = slot !== dragAnchor.value
  const anchorIndex = slots.value.indexOf(dragAnchor.value)
  const currentIndex = slots.value.indexOf(slot)
  if (anchorIndex < 0 || currentIndex < 0) return
  const direction = currentIndex >= anchorIndex ? 1 : -1
  const distance = Math.min(Math.abs(currentIndex - anchorIndex), 3)
  const range = Array.from({ length: distance + 1 }, (_, index) => slots.value[anchorIndex + index * direction]).filter((item): item is string => Boolean(item))
  if (range.some(item => isSlotOccupied(item))) return
  selectedSlots.value = range
}
function stopSlotDrag() {
  if (!draggingSlots.value) return
  if (!didDragSlots.value && dragAnchor.value) toggleSlot(dragAnchor.value)
  draggingSlots.value = false; dragAnchor.value = null; didDragSlots.value = false
}
async function requestReservation() { if (!props.residentId || !selectedArea.value || (bookingMode.value === 'time' && !selectedSlots.value.length)) return; const ordered = [...selectedSlots.value].sort((a, b) => parseMinutes(a) - parseMinutes(b)); const startTime = bookingMode.value === 'time' ? ordered[0]?.split(' – ')[0] : undefined; const endTime = bookingMode.value === 'time' ? ordered.at(-1)?.split(' – ')[1] : undefined; submitting.value = true; feedback.value = ''; try { await createReservation({ areaId: selectedArea.value.id, residentId: props.residentId, date: selectedDate.value, startTime, endTime }); feedback.value = bookingMode.value === 'day' ? 'Solicitação de diária enviada para análise.' : 'Solicitação enviada para análise.'; selectedSlots.value = []; showTimeSelection.value = false; emit('reservationCreated') } catch { feedback.value = 'Não foi possível solicitar este período.' } finally { submitting.value = false } }

onMounted(() => window.addEventListener('pointerup', stopSlotDrag))
onBeforeUnmount(() => window.removeEventListener('pointerup', stopSlotDrag))
</script>

<template>
  <section class="reservation-page">
    <div v-if="view === 'mine'" class="reservation-heading"><div><span class="eyebrow">{{ canManage ? 'Gestão de reservas' : 'Agenda pessoal' }}</span><h2>{{ canManage ? 'Reservas' : 'Minhas reservas' }}</h2><p>{{ canManage ? 'Analise as solicitações e acompanhe a agenda dos espaços.' : 'Acompanhe suas reservas e solicite novos agendamentos.' }}</p></div><button v-if="!canManage" class="primary-button" @click="openNewReservation">＋ Nova reserva</button></div>
    <div v-else class="reservation-heading new-heading"><div><button class="back-link" @click="view = 'mine'">← Minhas reservas</button><h2>Nova reserva</h2><p>Escolha a área, consulte a disponibilidade e selecione um horário.</p></div><label class="area-picker"><span>Área comum</span><select v-model="selectedAreaId" @change="resetTimeSelection"><option v-for="area in areas" :key="area.id" :value="area.id">{{ area.name }}</option></select></label></div>

    <template v-if="view === 'mine'"><div class="reservation-tabs" role="tablist" aria-label="Filtrar reservas"><button v-for="item in filterItems" :key="item.key" role="tab" :aria-selected="filter === item.key" :class="{ selected: filter === item.key }" @click="filter = item.key">{{ item.label }} <span>{{ item.key === 'all' ? myReservations.length : myReservations.filter(reservation => reservationState(reservation) === item.key).length }}</span></button></div><div v-if="!filteredReservations.length" class="reservation-empty panel"><span class="empty-icon" aria-hidden="true">▣</span><h3>{{ canManage ? 'Nenhuma solicitação encontrada' : filter === 'all' ? 'Você ainda não tem reservas' : 'Nenhuma reserva encontrada' }}</h3><p>{{ canManage ? 'Não há reservas correspondentes a este filtro.' : filter === 'all' ? 'Escolha um espaço comum e encontre o melhor horário para você.' : 'Tente outro filtro para consultar suas reservas.' }}</p><button v-if="!canManage" class="primary-button" @click="openNewReservation">Solicitar primeira reserva</button></div><div v-else class="reservation-list"><article v-for="reservation in filteredReservations" :key="reservation.id" class="reservation-card panel"><div class="area-thumb" aria-hidden="true">⌂</div><div class="reservation-card-main"><div class="reservation-card-title"><h3>{{ areaName(reservation.areaId) }}</h3><span :class="['reservation-badge', `badge-${reservationState(reservation)}`]"><i aria-hidden="true">{{ statusIcon(reservationState(reservation)) }}</i>{{ statusLabel(reservationState(reservation)) }}</span></div><div class="reservation-meta"><span>▣ {{ formatDate(reservation.date) }}</span><span>◷ {{ reservation.startTime && reservation.endTime ? `${reservation.startTime} – ${reservation.endTime}` : 'Dia inteiro' }}</span></div></div><div class="reservation-card-actions"><button class="outline-button" @click="viewReservationDetails(reservation)">Ver detalhes</button><button v-if="!canManage && canCancel(reservation)" class="text-button danger" :disabled="cancellingId === reservation.id" @click="cancel(reservation)">{{ cancellingId === reservation.id ? 'Cancelando...' : 'Cancelar reserva' }}</button></div></article></div></template>

    <div v-else class="reservation-layout">
      <article class="reservation-calendar panel"><div class="calendar-toolbar"><button class="calendar-nav" aria-label="Mês anterior" @click="changeMonth(-1)">←</button><div><strong>{{ monthLabel }}</strong><span>Selecione um dia para consultar os detalhes</span></div><button class="calendar-nav" aria-label="Próximo mês" @click="changeMonth(1)">→</button></div><div class="weekday-grid" aria-hidden="true"><span v-for="weekday in weekdays" :key="weekday">{{ weekday }}</span></div><div class="days-grid" role="grid" aria-label="Calendário de reservas"><button v-for="day in calendarDays" :key="day.key" type="button" role="gridcell" :aria-label="`${day.key}, ${availabilityLabel(dateStatus(day.key))}`" :aria-pressed="selectedDate === day.key" :class="['day-cell', `availability-${dateStatus(day.key)}`, { 'is-outside': !day.current, 'is-selected': selectedDate === day.key, 'is-today': day.key === todayKey }]" @click="selectDate(day.key)"><strong>{{ day.date.getDate() }}</strong><span class="availability-mark" aria-hidden="true"></span><small>{{ availabilityLabel(dateStatus(day.key)) }}</small></button></div><div class="availability-legend" aria-label="Legenda de disponibilidade"><span><i class="legend-mark available"></i>Disponível</span><span><i class="legend-mark partial"></i>Parcialmente ocupado</span><span><i class="legend-mark occupied"></i>Ocupado</span></div></article>
      <aside class="reservation-day-panel glass" aria-live="polite"><span class="eyebrow">Detalhes do dia</span><h3>{{ fullDateLabel }}</h3><table class="day-detail-table"><tbody><tr><th scope="row">Espaço</th><td>{{ selectedArea?.name }}</td></tr><tr><th scope="row">Disponibilidade</th><td><span :class="['day-status', `status-${selectedStatus}`]"><span class="status-symbol" aria-hidden="true"></span><strong>{{ availabilityLabel(selectedStatus) }}</strong></span></td></tr><tr v-if="occupiedPeriods.length"><th scope="row">Horários ocupados</th><td><span v-for="period in occupiedPeriods" :key="period" class="occupied-period">{{ period }}</span></td></tr><tr><th scope="row">Funcionamento</th><td>{{ selectedArea?.openingTime }}–{{ selectedArea?.closingTime }}</td></tr><tr><th scope="row">Capacidade</th><td>{{ selectedArea?.capacity ?? '—' }} pessoas</td></tr><tr><th scope="row">Duração máxima</th><td>2 horas ou diária</td></tr><tr><th scope="row">Aprovação</th><td>{{ selectedArea?.requiresApproval ? 'Necessária' : 'Automática' }}</td></tr></tbody></table><button v-if="!showTimeSelection" class="primary-button reservation-register" :disabled="selectedStatus === 'occupied' || selectedStatus === 'unavailable'" @click="openTimeSelection">Registrar reserva</button><section v-else class="slot-picker"><div class="slot-picker-head"><div><h4>Período da reserva</h4><p>Escolha uma diária ou clique e arraste por blocos de 30 minutos, até 2 horas.</p></div><button aria-label="Fechar seleção de horários" @click="resetTimeSelection">×</button></div><div class="booking-mode" role="radiogroup" aria-label="Tipo de reserva"><button role="radio" :aria-checked="bookingMode === 'time'" :class="{ selected: bookingMode === 'time' }" @click="setBookingMode('time')">Por horário</button><button role="radio" :aria-checked="bookingMode === 'day'" :disabled="occupiedPeriods.length > 0" :class="{ selected: bookingMode === 'day' }" @click="setBookingMode('day')">Dia inteiro</button></div><div v-if="bookingMode === 'time'" class="slot-grid"><button v-for="slot in slots" :key="slot" type="button" :disabled="isSlotOccupied(slot)" :aria-pressed="selectedSlots.includes(slot)" :class="['time-slot', { selected: selectedSlots.includes(slot), occupied: isSlotOccupied(slot) }]" @pointerdown.prevent="startSlotDrag(slot)" @pointerenter="extendSlotDrag(slot)" @keydown.enter.prevent="toggleSlot(slot)" @keydown.space.prevent="toggleSlot(slot)">{{ slot }}<span>{{ isSlotOccupied(slot) ? 'Ocupado' : selectedSlots.includes(slot) ? '✓' : '' }}</span></button></div><p v-if="bookingMode === 'day'" class="selected-summary">Reserva selecionada: <strong>dia inteiro</strong></p><p v-else-if="selectedInterval" class="selected-summary">Período selecionado: <strong>{{ selectedInterval }}</strong></p><p v-if="feedback" class="reservation-feedback" role="status">{{ feedback }}</p><button class="primary-button reservation-submit" :disabled="(bookingMode === 'time' && !selectedSlots.length) || submitting" @click="requestReservation">{{ submitting ? 'Enviando...' : bookingMode === 'day' ? 'Solicitar diária' : 'Solicitar reserva' }}</button></section></aside>
    </div>
  </section>
</template>

<style scoped>
